settings.custom_css:
selector{
    position: relative;
    overflow: hidden;
}

selector::before{
    content: "";
    position: absolute;
    width: 700px;
    height: 700px;
    background: #ff7a1a;
    border-radius: 50%;
    filter: blur(250px);
    opacity: 0.12;

    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);

    z-index: 0;
}

selector > *{
    position: relative;
    z-index: 1;
}

